def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    pressure_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        prev_bid = prev.get('bid')
        if prev_bid is not None:
            pressure_bids.append(float(prev_bid))
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 8:
            rich_count += 1

    max_prev = max(pressure_bids) if pressure_bids else 0.0
    avg_prev = sum(pressure_bids) / len(pressure_bids) if pressure_bids else 0.0

    scarcity = 1.0 - ((supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY))
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgent = (hp <= 2) or (no_water_days >= 2)
    semi_urgent = (hp <= 4) or (no_water_days >= 1)

    if urgent:
        target = max(DAILY_SALARY * 0.95, max_prev + 3.0)
        if supply <= 17:
            target = max(target, DAILY_SALARY * 1.15)
        return float(min(budget, target))

    if supply >= 23:
        if max_prev >= DAILY_SALARY * 1.5 and hp > 5 and no_water_days == 0:
            return float(min(budget, DAILY_SALARY * 0.18))
        target = max(DAILY_SALARY * 0.28, avg_prev * 0.45)
        return float(min(budget, target))

    if supply <= 17:
        if semi_urgent:
            target = max(DAILY_SALARY * 0.9, max_prev + 2.0, avg_prev + 4.0)
        else:
            if max_prev >= DAILY_SALARY * 1.6 and desperate_count == 0:
                target = DAILY_SALARY * 0.22
            else:
                target = max(DAILY_SALARY * 0.62, avg_prev * 0.8)
        if rich_count >= 2:
            target += 6.0
        return float(min(budget, target))

    base = DAILY_SALARY * (0.38 + 0.22 * scarcity)
    if max_prev > 0:
        if max_prev >= DAILY_SALARY * 1.4 and hp > 5 and no_water_days == 0:
            target = DAILY_SALARY * 0.25
        else:
            target = max(base, min(max_prev + 1.5, avg_prev + 10.0))
    else:
        target = base

    if semi_urgent:
        target = max(target, DAILY_SALARY * 0.72)
    if day >= 8 and hp <= 5:
        target = max(target, DAILY_SALARY * 0.82)

    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Alive opponents
    alive_opps = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If no opponents, bid just enough to get water
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace (immediate reaction)
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', None) or {}
        if prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate scarcity: with supply in [15,25], water units per day roughly 1 or 2.
    # If supply is high, competition lowers; if low, competition increases.
    # Use a conservative target bid around a fraction of DAILY_SALARY.
    if supply <= (MIN_SUPPLY + 0.5):
        scarcity_level = 1.0
    elif supply >= (MAX_SUPPLY - 0.5):
        scarcity_level = 0.3
    else:
        # linear between
        scarcity_level = 1.0 - 0.7 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))

    # My urgency based on hp and no_water_days
    hp = float(my_status.get('hp', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # If I'm at risk, bid more aggressively.
    urgent = (hp <= 3.0) or (no_water_days >= 1)

    # If yesterday saw very high bids, others may be competing hard today.
    # Use highest_prev_bid as a proxy for their pressure.
    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 1.25:
        pressure = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.9:
        pressure = 0.6
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        pressure = 0.3

    # Base bid target
    base = DAILY_SALARY * (0.35 + 0.35 * scarcity_level)

    # Adjust for urgency and pressure
    if urgent:
        base *= 1.55
    base *= (1.0 + 0.35 * pressure)

    # Ensure we don't overbid beyond what budget allows
    bid = min(my_status['budget'], base)

    # If yesterday pressure was extreme, slightly top up to beat likely bids, but cap.
    if highest_prev_bid > 0:
        target = min(my_status['budget'], max(bid, highest_prev_bid * (0.75 if not urgent else 0.95) + 2.0))
        bid = target

    # Final safety bounds: keep at least small positive if budget allows
    if my_status['budget'] <= 0:
        return 0.0
    if bid <= 0:
        return min(my_status['budget'], 1.0)
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    LOW_HP_THRESHOLD = 2
    CRITICAL_NO_WATER_DAYS = 1
    BASE_BID_MULTIPLIER = 0.75
    HIGH_COMPETITION_MULTIPLIER = 0.95
    INCREMENT_OVER_OPPONENT = 5.0
    SAFE_BID_MULTIPLIER = 0.4

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * SAFE_BID_MULTIPLIER)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    my_current_bid = 0.0

    if my_status['hp'] <= LOW_HP_THRESHOLD or my_status['no_water_days'] >= CRITICAL_NO_WATER_DAYS:
        my_current_bid = DAILY_SALARY * HIGH_COMPETITION_MULTIPLIER
    elif yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        average_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            my_current_bid = highest_prev_bid + INCREMENT_OVER_OPPONENT
            my_current_bid = min(my_current_bid, DAILY_SALARY * HIGH_COMPETITION_MULTIPLIER)
        else:
            my_current_bid = max(DAILY_SALARY * BASE_BID_MULTIPLIER, average_prev_bid + INCREMENT_OVER_OPPONENT)
    else:
        my_current_bid = DAILY_SALARY * BASE_BID_MULTIPLIER

    my_current_bid = max(0.0, min(my_status['budget'], my_current_bid))

    return my_current_bid
